css_extra:
/* ===== Componentes herdados da versão manual da aula ===== */
.mini { font-size:.78em; color:var(--tx-apoio); line-height:1.35 }
/* caixa de prompt (pre com campos destacados) */
.prompt { background:var(--ves); border:2px dashed var(--ve); border-radius:12px; padding:10px 14px 12px; margin:8px 0 }
.prompt .pt { font-family:var(--fonte-tit); font-weight:800; font-size:.74em; letter-spacing:.08em;
  text-transform:uppercase; color:var(--ve); margin:0 0 6px }
.prompt pre { white-space:pre-wrap; word-break:break-word; font-family:ui-monospace,'SF Mono',Menlo,Consolas,monospace;
  font-size:.82em; line-height:1.5; color:var(--p); margin:0 }
.prompt pre i { font-style:normal; background:var(--mk); border-radius:4px; padding:0 3px; font-weight:700 }
.bege .prompt { background:#fff }
.rev .resp .prompt { margin:8px 0 0; text-align:left }
/* tabelas com texto corrido: alinhadas à esquerda (o base centraliza a partir da 2ª coluna) */
#s2 .tb2 th, #s2 .tb2 td, #s6 .tb2 th, #s6 .tb2 td { text-align:left }
#s2 .tb2 td { padding:14px 12px }
#s2 .col { justify-content:center }
#s2 .col > .tb2 { flex:0 0 auto }
#s10 .tb2 th, #s10 .tb2 td { text-align:left }
#s10 .tb2 { font-size:15px }
#s10 .tb2 td, #s10 .tb2 th { padding:6px 10px }
#s10 .tb2 td:first-child { white-space:nowrap }
#s6 .tb2 td, #s6 .tb2 th { padding:7px 11px }
/* ocupar a altura disponível em vez de deixar um vazio grande no meio */
#s5 .bege { height:100% }
#s7 .bege { flex:1 1 0; display:flex; flex-direction:column; justify-content:center }
#s8 .slbd.g { grid-template-rows:minmax(0,1fr) auto !important }
#s8 .card { justify-content:center }
#s14 .col, #s15 .col, #s16 .col, #s17 .col, #s18 .col, #s19 .col, #s20 .col, #s21 .col { justify-content:center }
#s7 .bege { padding:12px 15px; margin:0 }
#s7 .bege p { font-size:var(--fs-corpo) }
#s23 .bege { margin:0; padding:12px 15px; flex:1 1 0; display:flex; flex-direction:column; justify-content:center }
#s3 .col, #s11 .col, #s13 .col, #s24 .col, #s26 .col { justify-content:center }
#s25 .ativ-rot { font-family:var(--fonte-tit); font-weight:800; font-size:.74em; letter-spacing:.14em;
  text-transform:uppercase; color:var(--ve) }
/* bônus: quatro prompts visíveis (o PDF/celular não abre o "revelar") */
#s22 .card { padding:9px 12px; flex:1 1 0; justify-content:center }
#s22 .prompt { margin:0; padding:8px 11px 10px }
#s22 .prompt .pt { font-size:.66em }
#s22 .prompt pre { font-size:.64em; line-height:1.45 }
